import{z as i,x as d,o as l,c as A,q as n,j as o,D as r,d as E,s,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const R=JSON.parse('{"title":"ALBERT 参数共享","description":"","frontmatter":{"title":"ALBERT 参数共享","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/albert-param-sharing.md","filePath":"llm/albert-param-sharing.md","lastUpdated":1791063341000}'),p={name:"llm/albert-param-sharing.md"};function m(L,a,h,T,b,f){const t=d("Mermaid");return l(),A("div",null,[a[2]||(a[2]=n('<h1 id="albert-参数共享" tabindex="-1">ALBERT 参数共享 <a class="header-anchor" href="#albert-参数共享" aria-label="Permalink to &quot;ALBERT 参数共享&quot;">​</a></h1><div class="epigraph"><p>跨层共享注意力与前馈权重，再把词表嵌入分解成低维再投影，参数量从层数和词表两端一起降下来。</p><footer>—— Lan et al., ALBERT: A Lite BERT for Self-supervised Learning of Language Representations, ICLR 2020</footer></div><p><a href="/llm/early-exit-adaptive">上一课</a>按例少算层，参数量不变。<a href="/llm/looped-transformer">循环 Transformer</a> 为算法任务共享块。本课把共享放回<a href="/llm/bert-encoder">BERT 编码器</a>的预训练设定：目标仍是双向 MLM，深度仍有 \\(L\\) 次前向，但 \\(L\\) 层共用一套注意力与 FFN。Lan 等人的 ALBERT 还加了嵌入因式分解。注意力续这一单元到此结束；下一单元从 HiPPO 接状态空间，不再把层共享当主线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><span class="marginnote">术语翻译：参数共享就是 \\(L\\) 层不用 \\(L\\) 套权重，而是所有层反复使用同一套 \\(F_\\theta\\)——像一本教材被十二个年级轮流使用，而不是每个年级印一本专属教材。深度（交互次数）还在，参数表只有一份。</span>BERT-large 的参数大部分在层重复与词表矩阵 \\(V\\times d\\) 上。加层立刻加参数，词表一涨嵌入先行爆炸。缺口不是再写一遍 MLM，而是：<strong>在保持双向深度（多次交互）的同时切断参数与 \\(L\\)、\\(V\\) 的线性绑定</strong>。Universal Transformer 为此引入 ACT；ALBERT 更保守——固定 \\(L\\) 次应用，训练目标与 BERT 同族，只改参数布局。</p><p>跨层共享与「层是功能特化的」紧张：上一课功能分化说深层头与浅层头不同。共享后分化只能沿迭代发生，表达力通常下降，换来的是可训更大等效深度或更小模型。</p><p><span class="marginnote">共享的是块内权重，不是把所有层的激活绑成同一个张量。每层仍有自己的隐状态；只是 \\(W\\) 的指针相同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三种共享：只共享注意力、只共享 FFN、全部共享。ALBERT 默认全部共享。嵌入写成 \\(E_{\\mathrm{vocab}}\\in\\mathbb{R}^{V\\times e}\\)，\\(e\\ll d\\)，再乘 \\(W_e\\in\\mathbb{R}^{e\\times d}\\) 升到模型维，参数从 \\(Vd\\) 降到 \\(Ve+ed\\)。位置嵌入仍可学习、仍截断长度，与 BERT 同类，不自动继承 T5 相对偏置。</p><p>训练目标上 ALBERT 用 MLM 加句序预测（SOP），替换 BERT 的 NSP。<span class="marginnote">术语翻译：NSP 让模型判断「这两句是不是原文里相邻的」，SOP 改成判断「这两句的先后顺序有没有被对调」——后者逼模型真正理解句间的因果与时序逻辑，而不是靠指代词之类的表面线索走捷径。</span>本课不把 SOP 展开：共享策略与句级任务正交，后课不要把 ALBERT 简化成「换了 NSP」。</p>',10)),(l(),o(B,null,{default:r(()=>[s(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20LR%0A%20%20OH%5B%22%E8%AF%8D%E8%A1%A8%E8%BA%AB%E4%BB%BD%3Cbr%2F%3EV%20%3D%203%20%E4%B8%87%E8%A1%8C%22%5D%20--%3E%20LE%5B%22%E4%BD%8E%E7%BB%B4%E5%B5%8C%E5%85%A5%20E%3A%20V%C3%97e%3Cbr%2F%3Ee%3D128%EF%BC%9A%E7%BA%A6%20384%20%E4%B8%87%E5%8F%82%E6%95%B0%22%5D%0A%20%20LE%20--%3E%20UP%5B%22%E5%8D%87%E7%BB%B4%E7%9F%A9%E9%98%B5%20W_e%3A%20e%C3%97d%3Cbr%2F%3E%E7%BA%A6%2013%20%E4%B8%87%E5%8F%82%E6%95%B0%22%5D%0A%20%20UP%20--%3E%20HD%5B%22%E6%A8%A1%E5%9E%8B%E7%A9%BA%E9%97%B4%20d%3D1024%22%5D%0A%20%20ALT%5B%22%E4%B8%8D%E5%88%86%E8%A7%A3%EF%BC%9A%E5%B5%8C%E5%85%A5%E7%9F%A9%E9%98%B5%20V%C3%97d%3Cbr%2F%3E%E2%89%88%203100%20%E4%B8%87%E5%8F%82%E6%95%B0%22%5D%20-.%E6%95%B4%E5%9D%97%E8%A2%AB%E6%9B%BF%E6%8D%A2%E6%8E%89.-%3E%20LE%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<h3 id="和-looped-的差别" tabindex="-1">和 looped 的差别 <a class="header-anchor" href="#和-looped-的差别" aria-label="Permalink to &quot;和 looped 的差别&quot;">​</a></h3><p>Looped 强调测试时改变 \\(T\\)，常留 prelude/coda。ALBERT 的 \\(L\\) 训练与推理相同，所有层共享，更像「为了塞进内存而去掉层间特化」。编码器分类、句向量池化都可以接在共享栈的最后一次输出上，与<a href="/llm/embedding-pooling">嵌入池化</a>兼容。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(L\\) 次同一 \\(F_\\theta\\) 迫使电路可复用，MLM 仍提供双向信号。经验上 ALBERT 在同等参数下可以更深，从而补回一部分共享损失；同等计算下不一定赢不共享的 BERT。嵌入分解假设词表身份可以先活在低维流形再展开到注意力空间，对大词表最划算，对很小的词表几乎无意义。</p><p>优化上共享参数的更新是各层梯度之和，浅层与深层的梯度会互相干扰。学习率与预热往往要重新扫，不能照抄 BERT-large。<span class="marginnote">直觉类比：共享参数的梯度是各层之和，好比一位老师同时给十二个年级上课，教案要同时迁就最深与最浅的学生——两头的需求会打架。所以优化配方（学习率、预热）必须重新摸，不能照抄不共享时的。</span>这与循环块的 RNN 式梯度是同一类现象，只是 \\(L\\) 固定、没有测试时加循环的承诺。</p><p><span class="marginnote">推理 FLOPs 仍按 \\(L\\) 层计，不因共享变便宜。共享只瘦存储与通信（分布式里一份权重）。要省计算看早退或稀疏，不看 ALBERT。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要指望共享栈在头功能上仍呈现「第 3 层句法、第 11 层语义」那种层特化叙事；探针应改沿迭代。生成式纯解码器较少直接套 ALBERT——词表矩阵与层宽的压力仍在，但今日更常用 GQA、MoE 去切另一维。本课结束编码器/注意力续里「深度怎么花钱」的讨论：下一课钱花在状态矩阵 \\(A\\) 上，而不是再共享一层 Transformer。</p>',8)),(l(),o(B,null,{default:r(()=>[s(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20Emb%5B%22%E8%AF%8D%E8%A1%A8%E4%BD%8E%E7%BB%B4%E5%B5%8C%E5%85%A5%22%5D%20--%3E%20Up%5B%22%E5%8D%87%E5%88%B0%20d%22%5D%0A%20%20Up%20--%3E%20B%5B%22%E5%85%B1%E4%BA%AB%E5%9D%97%20F_theta%22%5D%0A%20%20B%20--%3E%20B%0A%20%20B%20--%3E%20H%5B%22%E7%AC%AC%20L%20%E6%AC%A1%E8%BE%93%E5%87%BA%22%5D%0A%20%20H%20--%3E%20MLM%5B%22MLM%20%E5%A4%B4%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[E("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"ALBERT 用跨层共享切断参数与深度的绑定，用嵌入分解切断参数与词表的绑定。"),e("li",null,"深度（交互次数）仍在，层特化减弱；同等参数可更深，同等 FLOPs 不自动更快。"),e("li",null,"梯度是各层之和，优化比不共享更脆。"),e("li",null,"与 looped 的测试时 \\(T\\)、早退的按例深度不是同一旋钮。"),e("li",null,"出处：Lan et al., ICLR 2020。")],-1))])}const _=i(p,[["render",m]]);export{R as __pageData,_ as default};
